CREATE FUNCTION portal_trigger_allocation_guard() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM credit_inventory WHERE id=NEW.inventory_id AND type_id=NEW.type_id) THEN RAISE EXCEPTION 'CREDIT_TYPE_MISMATCH' USING ERRCODE = '23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM users u JOIN registrations r ON r.email=u.email AND r.status='approved' WHERE u.id=NEW.user_id AND COALESCE((SELECT status FROM participant_status_overrides WHERE user_id=u.id),'Checked in')='Checked in' AND (EXISTS(SELECT 1 FROM check_ins c WHERE c.user_id=u.id) OR EXISTS(SELECT 1 FROM manual_checkins m WHERE m.user_id=u.id AND m.verified_email=lower(u.email)))) THEN RAISE EXCEPTION 'CHECKIN_REQUIRED' USING ERRCODE = '23514'; END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER allocation_guard BEFORE INSERT ON credit_allocations
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_allocation_guard();

CREATE FUNCTION portal_trigger_allocation_recipient_insert() RETURNS trigger LANGUAGE plpgsql AS $portal$
