CREATE FUNCTION portal_trigger_membership_guard() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF (SELECT count(*) FROM memberships WHERE team_id=NEW.team_id)>=5 THEN RAISE EXCEPTION 'TEAM_FULL' USING ERRCODE = '23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM users u LEFT JOIN registrations r ON r.email=u.email WHERE u.id=NEW.user_id AND COALESCE(r.status,'pending') NOT IN ('rejected','cancelled')) THEN RAISE EXCEPTION 'REGISTRATION_REQUIRED' USING ERRCODE = '23514'; END IF;
 IF EXISTS(SELECT 1 FROM event_settings WHERE id=1 AND active=1 AND NEW.joined_at >= portal_json_extract(policy,'$.membershipFreeze')) THEN RAISE EXCEPTION 'MEMBERSHIP_FROZEN' USING ERRCODE = '23514'; END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER membership_guard BEFORE INSERT ON memberships
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_membership_guard();

CREATE FUNCTION portal_trigger_own_project_vote_checkin() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF EXISTS(SELECT 1 FROM projects p JOIN memberships m ON m.team_id=p.team_id WHERE p.id=NEW.project_id AND m.user_id=NEW.user_id) AND NOT EXISTS(SELECT 1 FROM users u JOIN registrations r ON r.email=u.email AND r.status='approved' WHERE u.id=NEW.user_id AND COALESCE((SELECT status FROM participant_status_overrides WHERE user_id=u.id),'Checked in')='Checked in' AND (EXISTS(SELECT 1 FROM check_ins c WHERE c.user_id=u.id) OR EXISTS(SELECT 1 FROM manual_checkins mc WHERE mc.user_id=u.id AND mc.verified_email=lower(u.email)))) THEN
RAISE EXCEPTION 'OWN_PROJECT_CHECKIN_REQUIRED' USING ERRCODE = '23514';
END IF;
 RETURN NEW;
END;
$portal$;
