CREATE FUNCTION portal_trigger_score_assignment_guard() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM judge_assignments a JOIN users u ON u.id=a.judge_id WHERE a.judge_id=NEW.judge_id AND a.team_id=NEW.team_id AND u.role='judge') THEN RAISE EXCEPTION 'ASSIGNMENT_REQUIRED' USING ERRCODE = '23514'; END IF;
 IF EXISTS(SELECT 1 FROM memberships WHERE user_id=NEW.judge_id AND team_id=NEW.team_id) THEN RAISE EXCEPTION 'JUDGE_CONFLICT' USING ERRCODE = '23514'; END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER score_assignment_guard BEFORE INSERT ON human_scores
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_score_assignment_guard();

