CREATE FUNCTION portal_trigger_snapshot_consistency() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF NEW.source_revision<>(SELECT version FROM scoring_revision WHERE id=1) THEN RAISE EXCEPTION 'SCORING_CHANGED_RETRY' USING ERRCODE = '23514'; END IF;
 IF EXISTS(SELECT 1 FROM result_snapshots) THEN RAISE EXCEPTION 'RESULTS_FROZEN' USING ERRCODE = '23514'; END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER snapshot_consistency BEFORE INSERT ON result_snapshots
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_snapshot_consistency();

CREATE FUNCTION portal_trigger_snapshot_immutable() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 RAISE EXCEPTION 'IMMUTABLE' USING ERRCODE = '23514';
 RETURN NEW;
END;
