CREATE FUNCTION portal_trigger_submission_team_checkin() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM memberships m JOIN users au ON au.id=m.user_id JOIN registrations ar ON ar.email=au.email AND ar.status='approved' WHERE m.team_id=NEW.team_id AND COALESCE((SELECT status FROM participant_status_overrides WHERE user_id=au.id),'Checked in')='Checked in' AND (EXISTS(SELECT 1 FROM check_ins c WHERE c.user_id=au.id) OR EXISTS(SELECT 1 FROM manual_checkins mc WHERE mc.user_id=au.id AND mc.verified_email=lower(au.email)))) THEN
RAISE EXCEPTION 'TEAM_CHECKIN_REQUIRED' USING ERRCODE = '23514';
END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER submission_team_checkin BEFORE INSERT ON submission_versions
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_submission_team_checkin();

CREATE FUNCTION portal_trigger_team_color_insert() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF NEW.color_key IS NOT NULL AND NEW.color_key NOT IN ('cobalt','forest','violet','ember','graphite','yellow','coral','grey') THEN
RAISE EXCEPTION 'TEAM_COLOR_INVALID' USING ERRCODE = '23514';
END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER team_color_insert BEFORE INSERT ON team_styles
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_team_color_insert();

