CREATE FUNCTION portal_trigger_vote_guard() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF (SELECT count(*) FROM votes WHERE voter_id=NEW.voter_id)>=3 THEN RAISE EXCEPTION 'VOTE_LIMIT' USING ERRCODE = '23514'; END IF;
 IF EXISTS(SELECT 1 FROM memberships WHERE user_id=NEW.voter_id AND team_id=NEW.team_id) THEN RAISE EXCEPTION 'OWN_TEAM' USING ERRCODE = '23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM check_ins c JOIN users u ON u.id=c.user_id JOIN registrations r ON r.email=u.email WHERE c.user_id=NEW.voter_id AND r.status='approved') THEN RAISE EXCEPTION 'CHECKIN_REQUIRED' USING ERRCODE = '23514'; END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER vote_guard BEFORE INSERT ON votes
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_vote_guard();

CREATE FUNCTION portal_trigger_vote_window() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF (SELECT active FROM event_settings WHERE id=1)<>1 OR NEW.created_at<(SELECT portal_json_extract(policy,'$.engagementOpen') FROM event_settings) OR NEW.created_at>=(SELECT portal_json_extract(policy,'$.engagementClose') FROM event_settings) THEN RAISE EXCEPTION 'ENGAGEMENT_CLOSED' USING ERRCODE = '23514'; END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER vote_window BEFORE INSERT ON votes
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_vote_window();

CREATE FUNCTION portal_trigger_voucher_credit_storage_insert() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF NEW.voucher_value IS NOT NULL AND (length(NEW.voucher_value)<1 OR length(NEW.voucher_value)>4000 OR NEW.ciphertext<>'') THEN
RAISE EXCEPTION 'INVALID_VOUCHER_STORAGE' USING ERRCODE = '23514';
END IF;
 RETURN NEW;
END;
$portal$;
