CREATE FUNCTION portal_trigger_whole_idea_lock() RETURNS trigger LANGUAGE plpgsql AS $portal$
BEGIN
 IF NEW.updated_at >= (SELECT portal_json_extract(policy,'$.ideaLock') FROM event_settings WHERE id=1) AND NOT EXISTS(SELECT 1 FROM write_guards WHERE token='admin-idea:'||NEW.team_id) THEN
RAISE EXCEPTION 'IDEA_LOCKED' USING ERRCODE = '23514';
END IF;
 RETURN NEW;
END;
$portal$;
CREATE TRIGGER whole_idea_lock BEFORE UPDATE ON ideas
 FOR EACH ROW EXECUTE FUNCTION portal_trigger_whole_idea_lock();

